export const documentsPage = {
  id: 'accompanying-documents',
  slug: 'accompanying-documents'
}

reference: {
    label: 'Document reference',
    hint: 'For example, GBHC1234567890.'
  },

accompanyingDocumentReference: (
    payload.accompanyingDocumentReference ?? ''
  ).trim(),

documentType: {
    label: 'Document type',
    placeholder: 'Select one'
  },

// The document-types service is the list, and the page offers all of it: every
// GBN-AG document type is selectable, each one coded on the outbound event from
// the GBN-AG document-type codelist (EUDPA-310). Design release 1 held
// HEALTH_CERTIFICATE back; EUDPA-310 offers it again.

dateOfIssue: {
    label: 'Date of issue',
    hint: 'For example, 12/12/2025'
  },

// Label every accepted extension, not the de-duplicated MIME types: .jpeg and
// .jpg share image/jpeg, so collapsing on MIME dropped JPG from the sentence
// while the input still accepted it. See EUDPA-523.

// Held at 10 so MAX_PAYLOAD_BYTES stays inside the ingress request-body cap in
// front of this service, which on CDP is nginx's 10 MiB default. EUDPA-518
// raised this to 50 for Design release 1; a 50MB upload never reaches the
// service, so the limit goes back until the ingress cap is raised with it.
const MAX_FILE_SIZE_MB = 10

return render(request, h, pageState, EMPTY_FORM, {
    errors: { file: OVERSIZE_FILE_MESSAGE },
    extra: { crumb }
  }).code(HTTP_STATUS_BAD_REQUEST)

// Every document field is mandatory per record and there is no edit
// page — a record added with blanks could never be completed in place,
// so presence is enforced at add time.

// `afterSave` is where a saved document lands the trader. Every successful
// save redirects back to the page — the POST mutated state, so a reload must
// not be able to replay it and append the document twice.

const savedEntry = {
    ...bare,
    accompanyingDocumentAttachmentType: attachmentTypeFor(filename),
    uploadId: outcome.uploadId,
    filename
  }

// The limit bullet stays on the page once rows exist, so the trader sees the
    // total on the populated state — not only on the empty page and not only
    // once they are refused.

scanTags: {
    complete: 'Check completed',
    virusFound: 'Virus found',
    scanning: 'Scanning for virus',
    unknown: 'Unknown'
  },

// The Status column reports the virus check, not a verdict on the file
  // (design release 1): "Scanning for virus" while it runs, "Check completed"
  // once it has. Virus found and Unknown have no design release 1 counterpart
  // and keep the wording this service already uses.

// Table cells built as HTML lose Nunjucks' auto-escaping, so anything the
// trader typed — a document reference, say — is escaped here before it is
// interpolated into a cell's markup.

try {
      await documentUploads.remove(entry.uploadId)
    } catch {
      return backToPage(request, h)
    }

export const SCAN_STATUS = {
  COMPLETE: 'COMPLETE',
  PENDING: 'PENDING',
  REJECTED: 'REJECTED'
}

// The one field a trader cannot fill in by accident, so it is the one that
// says a document is on its way (design release 1). A form carrying a chosen
// type is a part-filled document to be finished, not an empty form being
// skipped past; a form without one is left alone, uploading being optional.

// Continue submits the add-a-document fields along with it, so a part-filled
// form reaching here is a document the trader means to attach. Finish it —
// save it and return them to the page, or say what is missing — rather than
// drop it without a word.

{# javascript: true asks for the enhanced control — a drop zone with a
           live region naming the chosen file (design release 1). The plain
           input stays behind it for a trader whose JavaScript does not run. #}

// The enhancement must not duplicate the input or change the field the form
  // posts. This runs with JavaScript on, so it does not exercise the no-JS
  // fallback itself — that coverage is an open question on inc-137.

if (scanStatus === SCAN_STATUS.COMPLETE) {
    actionsCell.appendChild(viewFileLink(actionsCell, uploadId))
  }

announce: {
    safe: 'Document scan complete: the file is safe to use',
    virusFound:
      'Document scan failed: a virus was found. Remove the file and try again.'
  },

// A settled scan changes the Continue state and may add virus errors, so
// re-render from the server. The page is also reachable by POST (a blocked
// Continue), so navigate to its GET href rather than reloading.
